Lemma hc_zero_cell : forall E cs R FULL model b off n,
  CSOK E cs R FULL model -> chk_zero (kn cs) b off n = true ->
  forall a (w : nat), (w <= 8)%nat -> uE E b + off <= a -> a + Z.of_nat w <= uE E b + off + n ->
